def summary(rows):
    s={'wins':0,'losses':0,'draws':0,'unknown':0}
    names={'WIN':'wins','LOSS':'losses','DRAW':'draws'}
    for row in rows:
        s[names.get(row.get('derived'),'unknown')]+=1
    n=s['wins']+s['losses']
    s['rate']=s['wins']/n if n else None
    return s

